primaryQuery:
run: order_items extend {
  join_one: inventory_items is inventory_items
    on inventory_item_id = inventory_items.id
} -> {
  group_by: product_category is inventory_items.product_category
  aggregate:
    total_sales is sale_price.sum()
    margin_dollars is sale_price.sum() - inventory_items.cost.sum()
} -> {
  select:
    product_category
    total_sales
    margin_dollars
    margin_pct is round(margin_dollars / total_sales, 6)
  order_by: margin_pct desc
  limit: 5
}

verifyQuery:
run: inventory_items extend {
  join_one: oi is order_items on id = oi.inventory_item_id
} -> {
  where: oi.id is not null
  group_by: product_category
  aggregate:
    total_sales is oi.sale_price.sum()
    total_cost is cost.sum()
} -> {
  select:
    product_category
    total_sales
    margin_dollars is total_sales - total_cost
    margin_pct is round((total_sales - total_cost) / total_sales, 6)
  order_by: margin_pct desc
  limit: 5
} -> {
  select: product_category, total_sales, margin_dollars, margin_pct
  calculate: rank is row_number()
  order_by: margin_pct desc
}
